"""Shared board/Control prompt-library fragment; content is always inserted as text."""


def html():
    return r'''<style>
#prompt-library[hidden]{display:none!important}#prompt-library{position:fixed;inset:0;z-index:10000;background:#0009;overflow:auto;padding:2vh 2vw;color:#e7e9ef;font:14px system-ui;overflow-wrap:anywhere}#prompt-library .pl-shell{background:#181c25;border:1px solid #657084;border-radius:10px;max-width:1100px;margin:auto;padding:16px;min-width:0}#prompt-library header,#prompt-library .pl-tools{display:flex;gap:8px;align-items:center;flex-wrap:wrap}#prompt-library h2{margin:0;flex:1}#prompt-library label{display:flex;flex-direction:column;gap:4px;margin:8px 0}#prompt-library input,#prompt-library select,#prompt-library textarea,#prompt-library button{font:inherit;color:inherit;background:#242b38;border:1px solid #657084;border-radius:4px;padding:7px;max-width:100%;box-sizing:border-box}#prompt-library button{cursor:pointer}#prompt-library button:disabled{opacity:.5;cursor:default}#prompt-library :focus-visible{outline:3px solid #8cbfff;outline-offset:2px}#prompt-library textarea{width:100%;min-height:90px;white-space:pre-wrap}#prompt-library .pl-columns>*{min-width:0}#prompt-library fieldset{min-width:0}#prompt-library button{overflow-wrap:anywhere;white-space:normal}#prompt-library .pl-columns{display:grid;grid-template-columns:minmax(220px,1fr) minmax(0,2fr);gap:18px}#prompt-library .pl-row{border-bottom:1px solid #546070;padding:10px 0;overflow-wrap:anywhere}#prompt-library .pl-row button{width:100%;text-align:left}#prompt-library pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#10141d;padding:10px;user-select:text}#prompt-library #pl-status{white-space:pre-wrap;overflow-wrap:anywhere;padding:8px 0}#prompt-library #pl-status[data-error=true]{color:#ffb9b9}#prompt-library .pl-tags{display:flex;gap:8px;flex-wrap:wrap}#prompt-library .pl-tags label{display:inline-flex;flex-direction:row;align-items:center}#prompt-library .pl-hint{color:#b6c3d6}#prompt-library [hidden]{display:none!important}@media(max-width:650px){#prompt-library{padding:0}#prompt-library .pl-shell{border-radius:0;padding:12px}#prompt-library .pl-columns>*{min-width:0}#prompt-library fieldset{min-width:0}#prompt-library button{overflow-wrap:anywhere;white-space:normal}#prompt-library .pl-columns{grid-template-columns:minmax(0,1fr)}#prompt-library .pl-tools>*{flex:1 1 130px}#prompt-library header button{flex:0 1 auto}}
</style>
<section id="prompt-library" role="dialog" aria-modal="true" aria-labelledby="pl-heading" hidden><div class="pl-shell">
<header><h2 id="pl-heading">Prompt library</h2><button id="pl-close" type="button">Close library</button></header>
<p id="pl-context"></p><div id="pl-status" role="status" aria-live="polite"></div>
<div id="pl-switch" hidden><p>Unsaved input belongs to the current project. Save or discard it before switching.</p><button id="pl-switch-discard">Discard and switch</button><button id="pl-switch-stay">Stay in this project</button></div>
<div class="pl-tools"><label>Search title, body or tags<input id="pl-search" type="search"></label><label>Scope<select id="pl-scope"><option value="">All scopes</option><option>prebuilt</option><option>repo</option><option>project</option></select></label><label>Folder<select id="pl-folder"><option value="*">All folder contents</option><option value="">Ungrouped</option></select></label><button id="pl-clear">Clear filters</button><button id="pl-refresh">Refresh</button><button id="pl-new">New snippet</button></div>
<div id="pl-tags" class="pl-tags" aria-label="Required tags"></div><p id="pl-count"></p>
<div class="pl-columns"><div><div id="pl-list"></div><fieldset><legend>Folders in writable scope</legend><label>Folder scope<select id="pl-folder-scope"><option>project</option><option>repo</option></select></label><label>Existing folder<select id="pl-manage-folder"></select></label><label>Folder name<input id="pl-folder-name"></label><div class="pl-tools"><button id="pl-folder-create">Create folder</button><button id="pl-folder-rename">Rename folder</button><button id="pl-folder-delete">Delete empty folder</button></div></fieldset></div>
<div><section id="pl-detail" hidden><h3 id="pl-title"></h3><p id="pl-meta"></p><div class="pl-tools"><button id="pl-edit">Edit snippet</button><button id="pl-delete">Delete snippet</button><label>Duplicate to<select id="pl-duplicate-scope"><option>project</option><option>repo</option></select></label><button id="pl-duplicate">Duplicate</button></div><label>Move within scope<select id="pl-move-folder"></select></label><button id="pl-move">Move snippet</button><h4>Plain preview — stored body</h4><pre id="pl-plain" tabindex="0"></pre><button id="pl-copy-plain">Copy plain prompt</button><div id="pl-command" hidden><h4>Codex preview</h4><pre id="pl-codex" tabindex="0"></pre><button id="pl-copy-codex">Copy for Codex ($)</button><h4>Claude preview</h4><pre id="pl-claude" tabindex="0"></pre><button id="pl-copy-claude">Copy for Claude (/)</button></div><fieldset><legend>Rendered copy — variables and harness overrides</legend><label>Render harness<select id="pl-harness"><option>other</option><option>codex</option><option>claude</option></select></label><label>Variable values (JSON object)<textarea id="pl-render-vars">{}</textarea></label><button id="pl-copy-rendered">Render and copy</button><pre id="pl-rendered" tabindex="0"></pre><p id="pl-warnings"></p></fieldset></section>
<form id="pl-editor" hidden><h3 id="pl-editor-heading">Edit snippet</h3><label>Writable scope<select id="pl-edit-scope"><option>project</option><option>repo</option></select></label><label>Title<input id="pl-edit-title" required></label><label>Kind<select id="pl-edit-kind"><option value="plain">Plain prompt</option><option value="command">Command (explicit conversion)</option></select></label><label>Body<textarea id="pl-edit-body" required></textarea></label><label>Tags (JSON array of strings)<textarea id="pl-edit-tags">[]</textarea></label><label>Variables (JSON array)<textarea id="pl-edit-vars">[]</textarea></label><label>Harness overrides (JSON object)<textarea id="pl-edit-overrides">{}</textarea></label><label>Folder<select id="pl-edit-folder"></select></label><div class="pl-tools"><button type="submit" id="pl-save">Save snippet</button><button type="button" id="pl-cancel">Cancel edit</button></div><div id="pl-conflict" hidden><p>Conflict: input is retained. Reload the latest library, review its preview, then explicitly reapply your input.</p><button type="button" id="pl-conflict-reload">Reload latest</button><button type="button" id="pl-conflict-reapply" disabled>Reapply retained input to latest revision</button></div></form>
<label id="pl-fallback-label" hidden>Exact copy preview — select and copy manually<textarea id="pl-fallback" readonly></textarea></label></div></div></div></section>'''


def javascript():
    return r'''(function(){
'use strict';
const root=document.getElementById('prompt-library');if(!root)return;
const el=id=>document.getElementById('pl-'+id), scopes=['prebuilt','repo','project'];
let ctx=null,pending=null,epoch=0,fetchSeq=0,detailSeq=0,snapshot={items:[],stores:{}},selected=null,editor=null,dirty=false,busy=false,opener=null,selectedTags=new Set();
const status=(text,error=false)=>{el('status').textContent=text;el('status').dataset.error=String(error);};
const url=(context,path='')=>{const u=new URL(context.endpoint,location.href);u.pathname=u.pathname.replace(/\/$/,'')+path;return u.href;};
function filtered(items,query,scope,folder,tags){const q=query.trim().toLowerCase();return items.filter(i=>(!scope||i.scope===scope)&&(folder==='*'||(folder===''?!i.folder_id:JSON.stringify([i.scope,i.folder_id])===folder))&&tags.every(t=>(i.tags||[]).includes(t))&&(!q||[i.title,i.body,...(i.tags||[])].some(t=>String(t).toLowerCase().includes(q)))).sort((a,b)=>{const x=a.title.toLowerCase(),y=b.title.toLowerCase();return x<y?-1:x>y?1:a.identity<b.identity?-1:a.identity>b.identity?1:0;});}
async function request(context,path,body){let response;try{response=await fetch(url(context,path),body===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});}catch(e){throw new Error('Unavailable: '+e.message);}let data;try{data=await response.json();}catch(e){throw new Error('Unavailable: invalid server response');}if(!response.ok){const e=new Error((data.error||'request_failed')+(data.message?': '+data.message:'')+(data.count!==undefined?' ('+data.count+' items)':''));e.code=data.error;e.status=response.status;throw e;}return data;}
function option(select,value,text){const o=document.createElement('option');o.value=value;o.textContent=text;select.append(o);}
function folders(select,scope,all=false){const previous=select.value;select.replaceChildren();if(all)option(select,'*','All folder contents');option(select,'','Ungrouped');for(const s of scopes){if(scope&&s!==scope)continue;for(const f of snapshot.stores[s]?.folders||[])option(select,all?JSON.stringify([s,f.id]):f.id,(all?s+' / ':'')+f.name);}if([...select.options].some(o=>o.value===previous))select.value=previous;}
function manageFolders(){const select=el('manage-folder'),previous=select.value;select.replaceChildren();for(const f of snapshot.stores[el('folder-scope').value]?.folders||[])option(select,f.id,f.name);if([...select.options].some(o=>o.value===previous))select.value=previous;}
function draw(){folders(el('folder'),el('scope').value,true);manageFolders();const tags=[...new Set(snapshot.items.flatMap(i=>i.tags||[]))].sort();el('tags').replaceChildren();for(const tag of tags){const label=document.createElement('label'),box=document.createElement('input');box.type='checkbox';box.checked=selectedTags.has(tag);box.onchange=()=>{box.checked?selectedTags.add(tag):selectedTags.delete(tag);drawList();};label.append(box,document.createTextNode(tag));el('tags').append(label);}drawList();}
function drawList(){const matches=filtered(snapshot.items,el('search').value,el('scope').value,el('folder').value,[...selectedTags]);el('count').textContent=matches.length+' matching / '+snapshot.items.length+' total';el('list').replaceChildren();if(!matches.length){el('list').textContent=snapshot.items.length?'No matching snippets. Clear filters to see all.':'Library is empty.';return;}for(const item of matches){const row=document.createElement('div'),button=document.createElement('button');row.className='pl-row';button.textContent=item.title;button.onclick=()=>select(item.identity);const meta=document.createElement('p');meta.textContent=item.scope+' / '+(snapshot.stores[item.scope]?.folders?.find(f=>f.id===item.folder_id)?.name||'Ungrouped')+' · '+(item.tags||[]).join(', ');row.append(button,meta);el('list').append(row);}}
async function refresh(){if(!ctx)return;const context=ctx,ticket=epoch,seq=++fetchSeq;try{const data=await request(context);if(ticket!==epoch||seq!==fetchSeq)return;snapshot=data;detailSeq++;draw();if(selected){const item=snapshot.items.find(i=>i.identity===selected);if(item)showDetail(item);else{selected=null;el('detail').hidden=true;}}status('Library loaded.');return true;}catch(e){if(ticket!==epoch||seq!==fetchSeq)return;status('Load error — '+e.message,true);return false;}}
function showDetail(item){detailSeq++;selected=item.identity;el('detail').hidden=false;el('title').textContent=item.title;el('meta').textContent=ctx.contextName+' · '+item.scope+' · '+(snapshot.stores[item.scope]?.folders?.find(f=>f.id===item.folder_id)?.name||'Ungrouped');el('plain').textContent=item.body;el('codex').textContent='$'+item.body;el('claude').textContent='/'+item.body;el('command').hidden=item.kind!=='command';el('edit').disabled=item.scope==='prebuilt';el('delete').disabled=item.scope==='prebuilt';el('move').disabled=item.scope==='prebuilt';el('move-folder').disabled=item.scope==='prebuilt';folders(el('move-folder'),item.scope);el('move-folder').value=item.folder_id||'';el('rendered').textContent='';el('warnings').textContent='';}
function leaveEditor(){if(busy){status('Save in progress; wait before changing selection.',true);return false;}if(dirty&&!window.confirm('Discard unsaved snippet input?'))return false;editor=null;dirty=false;el('editor').hidden=true;el('conflict').hidden=true;return true;}
function select(identity){if(!leaveEditor())return;detailSeq++;const item=snapshot.items.find(i=>i.identity===identity);if(item)showDetail(item);}
function startEdit(item){if(!leaveEditor())return;const scope=item?.scope||'project';editor={id:item?.id||null,identity:item?.identity||null,scope,revision:snapshot.stores[scope]?.revision,context:ctx};dirty=false;el('editor').hidden=false;el('edit-scope').value=scope;el('edit-scope').disabled=!!item;el('edit-title').value=item?.title||'';el('edit-body').value=item?.body||'';el('edit-kind').value=item?.kind||'plain';el('edit-tags').value=JSON.stringify(item?.tags||[]);el('edit-vars').value=JSON.stringify(item?.variables||[]);el('edit-overrides').value=JSON.stringify(item?.harness_overrides||{});folders(el('edit-folder'),scope);el('edit-folder').value=item?.folder_id||'';el('edit-title').focus();}
async function mutate(scope,action,payload,revision,fromEditor=false){if(busy)return null;const context=ctx,ticket=epoch;busy=true;const controls=[...el('editor').querySelectorAll('input,textarea,select,button')].map(e=>[e,e.disabled]);controls.forEach(([e])=>e.disabled=true);try{const result=await request(context,'/'+encodeURIComponent(scope)+'/mutate',{...payload,action,revision});if(ticket!==epoch)return null;++fetchSeq;snapshot=result.snapshot;draw();status('Saved.');return result;}catch(e){if(ticket!==epoch)return null;status((e.status===409?'Conflict':e.status===428?'Reload required':'Save error')+' — '+e.message,true);if(fromEditor&&e.status===409){el('conflict').hidden=false;el('conflict-reapply').disabled=true;}return null;}finally{if(ticket===epoch){busy=false;controls.forEach(([e,disabled])=>e.disabled=disabled);}}}
function current(){return snapshot.items.find(i=>i.identity===selected);}
async function save(event){event?.preventDefault();if(!editor||editor.context!==ctx)return;try{const scope=el('edit-scope').value;const payload={title:el('edit-title').value,body:el('edit-body').value,kind:el('edit-kind').value,tags:JSON.parse(el('edit-tags').value),variables:JSON.parse(el('edit-vars').value),harness_overrides:JSON.parse(el('edit-overrides').value),folder_id:el('edit-folder').value||null};if(editor.id)payload.id=editor.id;const result=await mutate(scope,editor.id?'update':'create',payload,editor.revision,true);if(result){dirty=false;editor=null;el('editor').hidden=true;el('conflict').hidden=true;showDetail(result.item);el('edit').focus();}}catch(e){status('Input error — '+e.message,true);}}
async function copy(mode){const item=current();if(!item)return;status(mode==='rendered'?'Rendering…':'Preparing copy…');const context=ctx,ticket=epoch,seq=++detailSeq;const fallback=mode==='rendered'?el('rendered').textContent:mode==='plain'?item.body:(mode==='codex'?'$':'/')+item.body;el('fallback-label').hidden=false;el('fallback').value=fallback;let text;try{const path='/'+encodeURIComponent(item.scope)+'/'+encodeURIComponent(item.id);const body=mode==='rendered'?{harness:el('harness').value,variables:JSON.parse(el('render-vars').value)}:{mode};const result=await request(context,path+(mode==='rendered'?'/render':'/copy'),body);if(ticket!==epoch||seq!==detailSeq)return;text=result.text;el('fallback').value=text;if(mode==='rendered'){el('rendered').textContent=text;el('warnings').textContent=(result.warnings||[]).join('\n');}}catch(e){if(ticket===epoch&&seq===detailSeq)status((mode==='rendered'?'Render failed':'Copy preparation failed')+' — '+e.message+'. Select the retained exact preview to copy manually.',true);return;}try{if(!navigator.clipboard?.writeText)throw new Error('Clipboard unavailable');await navigator.clipboard.writeText(text);if(ticket===epoch&&seq===detailSeq)status('Copied.');}catch(e){if(ticket===epoch&&seq===detailSeq){status('Clipboard failed — '+e.message+'. Select the exact preview to copy manually.',true);el('fallback').focus();el('fallback').select();}}}
function doOpen(options){ctx={...options};pending=null;epoch++;fetchSeq++;detailSeq++;snapshot={items:[],stores:{}};selected=null;editor=null;dirty=false;busy=false;selectedTags.clear();el('editor').hidden=true;el('detail').hidden=true;el('switch').hidden=true;el('fallback-label').hidden=true;el('context').textContent='Selected project: '+ctx.contextName;el('search').value='';el('scope').value='';el('folder').value='*';draw();root.hidden=false;status('Loading…');el('search').focus();refresh();}
function open(options){if(!options?.endpoint||!options.contextKey||!options.contextName)throw new Error('Explicit library project context required');if(!root.hidden&&ctx?.contextKey===options.contextKey&&ctx.endpoint===options.endpoint){refresh();return;}if(dirty||busy){pending=options;el('switch').hidden=false;status('Project switch paused: input remains in '+ctx.contextName+'.',true);return;}if(root.hidden)opener=document.activeElement;doOpen(options);}
function close(){if(busy){status('Save in progress; wait before closing.',true);return false;}if(!leaveEditor())return false;const callback=ctx?.onClose;epoch++;detailSeq++;root.hidden=true;pending=null;ctx=null;opener?.focus();callback?.();return true;}
el('close').onclick=close;el('search').oninput=drawList;el('scope').onchange=draw;el('folder').onchange=drawList;el('refresh').onclick=refresh;el('clear').onclick=()=>{el('search').value='';el('scope').value='';el('folder').value='*';selectedTags.clear();draw();};el('new').onclick=()=>startEdit(null);el('edit').onclick=()=>startEdit(current());el('cancel').onclick=()=>{if(leaveEditor())el('new').focus();};el('editor').onsubmit=save;el('editor').oninput=()=>{dirty=true;};el('edit-scope').onchange=()=>{if(!editor?.id){editor.scope=el('edit-scope').value;editor.revision=snapshot.stores[editor.scope]?.revision;folders(el('edit-folder'),editor.scope);dirty=true;}};
el('delete').onclick=async()=>{const item=current();if(!item||!window.confirm('Delete snippet “'+item.title+'”?'))return;const result=await mutate(item.scope,'delete',{id:item.id},item.revision);if(result){selected=null;el('detail').hidden=true;el('new').focus();}};
el('duplicate').onclick=async()=>{const item=current(),scope=el('duplicate-scope').value;if(!item)return;const result=await mutate(scope,'duplicate',{source_scope:item.scope,source_id:item.id},snapshot.stores[scope]?.revision);if(result)showDetail(result.item);};
el('move').onclick=async()=>{const item=current();if(!item)return;const result=await mutate(item.scope,'move',{id:item.id,folder_id:el('move-folder').value||null},item.revision);if(result)showDetail(result.item);};
el('folder-scope').onchange=manageFolders;for(const action of ['create','rename','delete'])el('folder-'+action).onclick=async()=>{const scope=el('folder-scope').value;await mutate(scope,'folder_'+action,{id:el('manage-folder').value,name:el('folder-name').value},snapshot.stores[scope]?.revision);};
el('conflict-reload').onclick=async()=>{const loaded=await refresh();if(loaded&&editor){const exists=!editor.identity||snapshot.items.some(i=>i.identity===editor.identity);el('conflict-reapply').disabled=!exists;if(!exists)status('Conflict: snippet was deleted. Retained input cannot overwrite a missing item; create a new snippet after copying your input.',true);}};el('conflict-reapply').onclick=()=>{if(editor){editor.revision=snapshot.stores[editor.scope]?.revision;el('conflict-reapply').disabled=true;status('Latest revision selected. Review retained input, then save to reapply.');}};
for(const mode of ['plain','codex','claude','rendered'])el('copy-'+mode).onclick=()=>copy(mode);
el('switch-stay').onclick=()=>{pending=null;el('switch').hidden=true;};el('switch-discard').onclick=()=>{if(busy){status('Save in progress; wait before switching.',true);return;}if(pending){const next=pending;dirty=false;doOpen(next);}};
window.addEventListener('focus',()=>{if(!root.hidden)refresh();});root.addEventListener('keydown',event=>{if(event.key==='Escape'){event.preventDefault();close();}if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='f'&&!event.target.closest('input,textarea,select,[contenteditable]')){event.preventDefault();el('search').focus();}if(event.key==='Tab'){const focusable=[...root.querySelectorAll('button,input,select,textarea,[tabindex="0"]')].filter(e=>!e.disabled&&e.getClientRects().length);if(!focusable.length)return;const first=focusable[0],last=focusable[focusable.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}});
window.PromptLibraryUI={open,close};
})();'''
